#include <native/resources.h>
#include <iostream>

namespace native_embedded
{
    // Return the immutable bytes generated by tools/rc.
    std::span<const std::uint8_t> resource_data();
}
int main(int argc, char **argv) {
    try {
        if (argc != 2) return 1;
        const auto embedded = native::resources::decode(native_embedded::resource_data());
        if (embedded.encode() != native::resources::load(argv[1]).encode()) return 1;
        const auto &value = embedded.get("assets.greeting", {});
        return std::string(value.data.begin(), value.data.end()) ==
            "Hello from a resource pack.\n" ? 0 : 1;
    } catch (const std::exception &error) {
        std::cerr << error.what() << '\n';
        return 1;
    }
}
